// Seeds member_stories from the public Members-page cards (src/data/members.ts), so the
// portal directory has content on day one. See docs/plans/member-portal.md.
//
// The cards name people by first name ("Sree & Prameela") and the register's real names are
// private (the repo is public), so the matching is done INSIDE the database: this module
// only turns the public card text into SQL, and the SQL joins it to member_people at run
// time. Nothing private is written to the repo or to the generated file.
//
// What a seeded story is: the card's text, already approved and published (the cards are on
// tvc.farm today), copied onto every person the card names. The card is about the household, so
// both people get the same bio and family; a "why" given as two quotes goes one to each person,
// and a profile link goes to the person at the same position in the card's name. It is also the
// person's draft, so when they open "Your story" their existing text is there to edit. An
// existing story is never overwritten (on conflict do nothing), so re-running is safe.

const TAG = 'seed';

// "Sree & Prameela" -> ['sree', 'prameela']; "Amit Gupta" -> ['amit gupta'];
// "Shalini & Amit Jain" -> ['shalini', 'amit jain']. A token matches a person whose full name
// equals it or starts with it followed by a space (so a first name matches "Sree Kumar").
export function cardTokens(cardName) {
  return cardName
    .split(/\s+&\s+|\s+and\s+/i)
    .map((t) => t.trim().toLowerCase().replace(/\s+/g, ' '))
    .filter(Boolean);
}

const asText = (v) => (typeof v === 'string' ? v.trim() : '');
const asList = (v) => (Array.isArray(v) ? v.map(asText) : typeof v === 'string' && v.trim() ? [v.trim()] : []);

// The cards that have something to say. An empty card (just a name, ~20 of them) is left alone.
export function seedCards(members) {
  const out = [];
  for (const m of members) {
    const card = {
      cardName: m.name,
      tokens: cardTokens(m.name),
      bio: asText(m.bio),
      family: asText(m.family),
      whys: asList(m.whyTVC),
      socials: asList(m.social),
    };
    if (card.tokens.length === 0) continue;
    if (card.bio || card.family || card.whys.length) out.push(card);
  }
  return out;
}

// Postgres dollar-quoting: no escaping needed, as long as the text can't close it.
function q(text) {
  const open = `$${TAG}$`;
  if (text.includes(open)) throw new Error(`Card text contains ${open}; pick another quote tag.`);
  return `${open}${text}${open}`;
}
const textArray = (list) => (list.length ? `array[${list.map(q).join(', ')}]::text[]` : 'array[]::text[]');

const HEADER = `-- Seeds member_stories from the public Members-page cards (generated by
-- scripts/seed-member-stories.mjs; see docs/plans/member-portal.md). Run in the TVC ERP
-- SQL editor. The text below is the public card text only; people are matched to cards inside
-- the database, so nothing private is in this file.
`;

// An override is a farm plot ("F-12"), or { plot: "F-12", names: { om: "omshivaprakash" } } to also say
// how a name on the card is spelled in the register. Either pins the card to that household.
export function normalizeOverrides(overrides = {}) {
  const plots = {};
  const aliases = {};
  for (const [card, value] of Object.entries(overrides)) {
    const plot = typeof value === 'string' ? value : value?.plot;
    if (typeof plot !== 'string' || !/^F-\d{2}$/.test(plot)) throw new Error(`Override for "${card}" needs a farm plot like "F-12".`);
    plots[card] = plot;
    if (value && typeof value === 'object' && value.names) {
      aliases[card] = Object.fromEntries(Object.entries(value.names).map(([k, v]) => [k.trim().toLowerCase(), String(v).trim().toLowerCase()]));
    }
  }
  return { plots, aliases };
}

function setup(cards, overrides) {
  const { plots, aliases } = normalizeOverrides(overrides);
  const overrideRows = Object.entries(plots);
  // The tokens in seed_cards are what names are matched on; an alias swaps in the register's spelling.
  cards = cards.map((c) => ({ ...c, tokens: c.tokens.map((t) => aliases[c.cardName]?.[t] ?? t) }));
  return `${HEADER}
drop table if exists seed_people, seed_elim, seed_core, seed_picks, seed_loose, seed_strict, seed_resolved, seed_household_match, seed_token_matches, seed_overrides, seed_cards;

create temp table seed_cards (
  card_name text primary key,
  tokens text[] not null,
  bio text not null,
  family text not null,
  whys text[] not null,
  socials text[] not null
);
insert into seed_cards (card_name, tokens, bio, family, whys, socials) values
${cards.map((c) => `  (${q(c.cardName)}, ${textArray(c.tokens)}, ${q(c.bio)}, ${q(c.family)}, ${textArray(c.whys)}, ${textArray(c.socials)})`).join(',\n')};

-- A card that matched no household, or more than one, can be pinned to a farm plot here.
create temp table seed_overrides (card_name text primary key, farm_unit text not null);
${overrideRows.length ? `insert into seed_overrides (card_name, farm_unit) values\n${overrideRows.map(([n, f]) => `  (${q(n)}, ${q(f)})`).join(',\n')};` : '-- (none)'}

-- Which people each name on a card could be: an active person whose full name is the token,
-- or starts with it (a first name).
create temp table seed_token_matches as
select c.card_name, t.pos::int as pos, p.id as person_id, hm.household_id
from seed_cards c
cross join lateral unnest(c.tokens) with ordinality as t(token, pos)
join member_people p
  on p.active and (lower(btrim(p.full_name)) = t.token or lower(btrim(p.full_name)) like t.token || ' %')
join member_household_members hm on hm.person_id = p.id;

-- A household fits a card if every name on the card is someone in it.
create temp table seed_household_match as
select m.card_name, m.household_id
from seed_token_matches m
join seed_cards c on c.card_name = m.card_name
group by m.card_name, m.household_id, c.tokens
having count(distinct m.pos) = cardinality(c.tokens);

-- One household per card: the override if there is one, else the only one that fits.
create temp table seed_resolved as
with counted as (
  select card_name, count(*)::int as n_candidates, min(household_id::text)::uuid as only_household
  from seed_household_match group by card_name
)
select c.card_name,
       coalesce(oh.id, case when cn.n_candidates = 1 then cn.only_household end) as household_id,
       coalesce(cn.n_candidates, 0) as n_candidates,
       (o.card_name is not null) as pinned
from seed_cards c
left join counted cn on cn.card_name = c.card_name
left join seed_overrides o on o.card_name = c.card_name
left join member_households oh on oh.farm_unit = o.farm_unit;

-- The person behind each name on a card. In a household nobody pinned, a name must match exactly
-- (one person, a full name equal to it or starting with it). In a household you pinned with
-- --overrides, the match is looser, best kind first, because you have already said which household:
--   1 first word is the name   2 any word is the name   3 a word starts with it
--   4 a word contains it       5 a word shares its first three letters
--   6 (below) the only name and the only primary member left in the household
-- A name is taken only if exactly one person matches at the best kind, and nobody is used twice.
create temp table seed_strict as
select r.card_name, m.pos, (array_agg(m.person_id))[1] as person_id, 1 as tier
from seed_resolved r
join seed_token_matches m on m.card_name = r.card_name and m.household_id = r.household_id
where r.household_id is not null and not r.pinned
group by r.card_name, m.pos
having count(distinct m.person_id) = 1;

create temp table seed_loose as
select r.card_name, t.pos::int as pos, p.id as person_id,
  case
    when lower(btrim(p.full_name)) = t.token or lower(btrim(p.full_name)) like t.token || ' %' then 1
    when t.token = any (w.words) then 2
    when exists (select 1 from unnest(w.words) x where x like t.token || '%') then 3
    when length(t.token) >= 4 and exists (select 1 from unnest(w.words) x where x like '%' || t.token || '%') then 4
    when length(t.token) >= 4 and exists (select 1 from unnest(w.words) x where left(x, 3) = left(t.token, 3)) then 5
  end as tier
from seed_resolved r
join seed_cards c on c.card_name = r.card_name
cross join lateral unnest(c.tokens) with ordinality as t(token, pos)
join member_household_members hm on hm.household_id = r.household_id
join member_people p on p.id = hm.person_id and p.active
cross join lateral (select string_to_array(lower(btrim(p.full_name)), ' ') as words) w
where r.pinned and r.household_id is not null;

create temp table seed_picks as
select card_name, pos, (array_agg(person_id))[1] as person_id, min(tier) as tier
from (
  select l.*, min(tier) over (partition by card_name, pos) as best from seed_loose l where tier is not null
) x
where tier = best
group by card_name, pos
having count(distinct person_id) = 1
union all
select card_name, pos, person_id, tier from seed_strict;

create temp table seed_core as
select a.card_name, a.pos, a.person_id, a.tier
from seed_picks a
where (select count(*) from seed_picks b where b.card_name = a.card_name and b.person_id = a.person_id) = 1;

-- Last resort, pinned households only: a card with exactly one name still unmatched, and exactly one
-- primary member (an owner) of the household still unmatched, are taken to be the same person.
create temp table seed_elim as
with open_pos as (
  select r.card_name, t.pos::int as pos
  from seed_resolved r
  join seed_cards c on c.card_name = r.card_name
  cross join lateral unnest(c.tokens) with ordinality as t(token, pos)
  where r.pinned and r.household_id is not null
    and not exists (select 1 from seed_core k where k.card_name = r.card_name and k.pos = t.pos)
), open_people as (
  select r.card_name, p.id as person_id
  from seed_resolved r
  join member_household_members hm on hm.household_id = r.household_id and hm.role = 'owner'
  join member_people p on p.id = hm.person_id and p.active
  where r.pinned and r.household_id is not null
    and not exists (select 1 from seed_core k where k.card_name = r.card_name and k.person_id = p.id)
)
select o.card_name, (array_agg(o.pos))[1] as pos, (array_agg(pp.person_id))[1] as person_id, 6 as tier
from open_pos o
join open_people pp on pp.card_name = o.card_name
group by o.card_name
having count(distinct o.pos) = 1 and count(distinct pp.person_id) = 1;

create temp table seed_people as
select card_name, pos, person_id, tier from seed_core
union all
select card_name, pos, person_id, tier from seed_elim;
`;
}

const PREVIEW = `
-- PREVIEW: nothing is written. One row per card; fix any that are not "matched" with
-- --overrides (card name -> farm plot) and regenerate.
select c.card_name,
       case when r.household_id is not null then 'matched'
            when r.n_candidates > 1 then 'AMBIGUOUS (' || r.n_candidates || ' households)'
            else 'NO HOUSEHOLD' end as status,
       coalesce(h.farm_unit, '-') as farm_unit,
       (select count(*) from seed_people sp where sp.card_name = c.card_name) || ' of ' || cardinality(c.tokens) as people_found,
       (select count(*) from seed_people sp join member_stories s on s.person_id = sp.person_id where sp.card_name = c.card_name) as already_have_a_story
from seed_cards c
join seed_resolved r on r.card_name = c.card_name
left join member_households h on h.id = r.household_id
order by (r.household_id is null) desc, (select count(*) from seed_people sp where sp.card_name = c.card_name) < cardinality(c.tokens) desc, c.card_name;
`;

const APPLY = `
-- SEED: writes one approved, published story per person found above (skipping anyone who
-- already has a story), and one row in staff_audit_log. Safe to run again.
with ins as (
  insert into member_stories (person_id, draft, draft_public, status, approved, approved_public, approved_at)
  select sp.person_id, s.story, true, 'approved', s.story, true, now()
  from seed_people sp
  join seed_cards c on c.card_name = sp.card_name
  cross join lateral (
    select jsonb_build_object(
      'bio', c.bio,
      'family', c.family,
      'why', coalesce(c.whys[sp.pos], c.whys[1], ''),
      'social', coalesce(c.socials[sp.pos], '')
    ) as story
  ) s
  on conflict (person_id) do nothing
  returning person_id
), logged as (
  insert into staff_audit_log (action, module, detail)
  select 'members.stories.seed', 'members',
         jsonb_build_object('inserted', (select count(*) from ins), 'cards', (select count(*) from seed_cards))
  returning detail
)
select (select count(*) from ins) as stories_added,
       (select count(*) from seed_people) as people_matched,
       (select count(*) from seed_cards) as cards_with_text;
`;


const DIAGNOSE = `
-- DIAGNOSE: nothing is written, and no register name is shown. For every name on a card that
-- found no household, how many active people match it exactly (a full name equal to it, or
-- starting with it), in which farm plots, and then looser guesses (the name appears anywhere in a
-- full name; the first three letters appear) so a different spelling, initials or a surname-first
-- name shows up as a farm plot to pin with --overrides.
select c.card_name, t.pos::int as name_no, t.token as name_on_card,
  (select count(*) from member_people p
    where p.active and (lower(btrim(p.full_name)) = t.token or lower(btrim(p.full_name)) like t.token || ' %')) as people_exact,
  (select string_agg(distinct h.farm_unit, ', ' order by h.farm_unit)
    from member_people p join member_household_members m on m.person_id = p.id join member_households h on h.id = m.household_id
    where p.active and (lower(btrim(p.full_name)) = t.token or lower(btrim(p.full_name)) like t.token || ' %')) as plots_exact,
  (select string_agg(distinct h.farm_unit, ', ' order by h.farm_unit)
    from member_people p join member_household_members m on m.person_id = p.id join member_households h on h.id = m.household_id
    where p.active and lower(p.full_name) like '%' || t.token || '%') as plots_name_anywhere,
  (select string_agg(distinct h.farm_unit, ', ' order by h.farm_unit)
    from member_people p join member_household_members m on m.person_id = p.id join member_households h on h.id = m.household_id
    where p.active and lower(p.full_name) like '%' || left(t.token, 3) || '%') as plots_first_3_letters
from seed_cards c
join seed_resolved r on r.card_name = c.card_name
cross join lateral unnest(c.tokens) with ordinality as t(token, pos)
where r.household_id is null
order by c.card_name, t.pos;
`;

const VERIFY = `
-- VERIFY: nothing is written. For every card pinned with --overrides, who each name on the card
-- matched. THIS SHOWS REGISTER NAMES: check it yourself, and do not paste it anywhere. Every row
-- should be the right person; NOT FOUND means that name will not get a story.
select c.card_name,
       t.token as name_on_card,
       coalesce(p.full_name, 'NOT FOUND') as register_name,
       case sp.tier when 1 then 'exact' when 2 then 'a word of the name' when 3 then 'a word starts with it'
                    when 4 then 'a word contains it' when 5 then 'same first 3 letters'
                    when 6 then 'the only owner left in the household' end as how_matched,
       h.farm_unit
from seed_cards c
join seed_resolved r on r.card_name = c.card_name and r.pinned
cross join lateral unnest(c.tokens) with ordinality as t(token, pos)
left join seed_people sp on sp.card_name = c.card_name and sp.pos = t.pos
left join member_people p on p.id = sp.person_id
left join member_households h on h.id = r.household_id
order by c.card_name, t.pos;
`;

// mode 'preview', 'diagnose' and 'verify' read only; mode 'apply' writes.
export function buildSeedSql(cards, { mode, overrides = {} }) {
  if (!['preview', 'diagnose', 'verify', 'apply'].includes(mode)) throw new Error('mode must be preview, diagnose, verify or apply');
  return setup(cards, overrides) + { preview: PREVIEW, diagnose: DIAGNOSE, verify: VERIFY, apply: APPLY }[mode];
}
